@app.route("/api/products/search", methods=["GET"])
def search_products():
    q = request.args.get("q", "").strip()
    category = request.args.get("category")

    if not q:
        return jsonify([])

    sql = "SELECT * FROM products WHERE name LIKE ? COLLATE NOCASE"
    params = [f"%{q}%"]

    if category:
        sql += " AND category = ?"
        params.append(category)

    sql += " ORDER BY id"
    rows = db.execute(sql, params)
    return jsonify(rows)


